// Copyright (c) Microsoft Corporation. All rights reserved.
// Licensed under the MIT License.

using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    internal class ResponseErrorAotConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var doc = JsonDocument.ParseValue(ref reader);
            return ReadResponseError(doc.RootElement);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            if (value.Code != null)
            {
                writer.WriteString("code", value.Code);
            }
            if (value.Message != null)
            {
                writer.WriteString("message", value.Message);
            }
            if (value.Target != null)
            {
                writer.WriteString("target", value.Target);
            }
            if (value.Details != null && value.Details.Count > 0)
            {
                writer.WriteStartArray("details");
                foreach (var detail in value.Details)
                {
                    Write(writer, detail, options);
                }
                writer.WriteEndArray();
            }
            writer.WriteEndObject();
        }

        private static ResponseError ReadResponseError(JsonElement element)
        {
            string code = null;
            string message = null;
            string target = null;
            List<ResponseError> details = null;

            foreach (var prop in element.EnumerateObject())
            {
                switch (prop.Name)
                {
                    case "code":
                        code = prop.Value.ValueKind == JsonValueKind.String ? prop.Value.GetString() : null;
                        break;
                    case "message":
                        message = prop.Value.ValueKind == JsonValueKind.String ? prop.Value.GetString() : null;
                        break;
                    case "target":
                        target = prop.Value.ValueKind == JsonValueKind.String ? prop.Value.GetString() : null;
                        break;
                    case "details":
                        if (prop.Value.ValueKind == JsonValueKind.Array)
                        {
                            details = new List<ResponseError>();
                            foreach (var item in prop.Value.EnumerateArray())
                            {
                                details.Add(ReadResponseError(item));
                            }
                        }
                        break;
                }
            }

            return new ResponseError(code, message, target, default, null, details);
        }
    }
